use serde::{Deserialize, Serialize};

use crate::{Account, PatchSetNumber, Timestamp};

/// An entry of a change's log (`ChangeMessageInfo`): a review comment
/// summary, a vote, a status change, or a bot message.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ChangeMessage {
    pub id: String,
    /// Absent for messages posted by Gerrit itself.
    pub author: Option<Account>,
    /// Set when the message was posted on behalf of `author`.
    pub real_author: Option<Account>,
    pub date: Timestamp,
    pub message: String,
    /// E.g. `autogenerated:gerrit:merged` or `autogenerated:jenkins`.
    pub tag: Option<String>,
    /// The patch set the message belongs to.
    pub revision: Option<PatchSetNumber>,
}

impl ChangeMessage {
    /// True for messages tagged as automatically generated (CI, Gerrit
    /// itself); a UI may fold these.
    pub fn is_autogenerated(&self) -> bool {
        self.tag
            .as_deref()
            .is_some_and(|t| t.starts_with("autogenerated:"))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn autogenerated_by_tag() {
        let mut m = ChangeMessage {
            id: "m1".into(),
            author: None,
            real_author: None,
            date: "2024-01-01T00:00:00Z".parse().unwrap(),
            message: "Uploaded patch set 1.".into(),
            tag: None,
            revision: Some(PatchSetNumber(1)),
        };
        assert!(!m.is_autogenerated());
        m.tag = Some("autogenerated:gerrit:newPatchSet".into());
        assert!(m.is_autogenerated());
        m.tag = Some("mytag".into());
        assert!(!m.is_autogenerated());
    }
}
